  { id: 'bio10-m6-s028', questionId: 'bio10-m6-q028', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Vi khuẩn sinh sản phổ biến bằng gì?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Phân đôi”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-s029', questionId: 'bio10-m6-q029', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Nấm men thường sinh sản vô tính bằng gì?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Nảy chồi”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-s030', questionId: 'bio10-m6-q030', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Ngoại enzyme của vi sinh vật giúp gì?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Phân giải polymer ngoài tế bào để hấp thu”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-s031', questionId: 'bio10-m6-q031', recognition: 'Dạng yếu tố ảnh hưởng và kiểm soát: phân tích tác động của nhiệt độ, pH, độ ẩm, hóa chất hoặc kháng sinh.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Làm lạnh bảo quản thực phẩm chủ yếu vì sao?” thuộc dạng yếu tố ảnh hưởng và kiểm soát: phân tích tác động của nhiệt độ, pH, độ ẩm, hóa chất hoặc kháng sinh.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Làm chậm enzyme và sinh trưởng vi sinh vật”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Kháng sinh không điều trị virus; hiệu quả kiểm soát phụ thuộc nồng độ, thời gian và đối tượng.'], reviewSuggestions: ['Ôn yếu tố vật lí, hóa học và nguyên tắc dùng kháng sinh.'] },
  { id: 'bio10-m6-s032', questionId: 'bio10-m6-q032', recognition: 'Dạng yếu tố ảnh hưởng và kiểm soát: phân tích tác động của nhiệt độ, pH, độ ẩm, hóa chất hoặc kháng sinh.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Kháng sinh không trị cúm vì sao?” thuộc dạng yếu tố ảnh hưởng và kiểm soát: phân tích tác động của nhiệt độ, pH, độ ẩm, hóa chất hoặc kháng sinh.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Cúm do virus, thiếu các đích tế bào vi khuẩn”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Kháng sinh không điều trị virus; hiệu quả kiểm soát phụ thuộc nồng độ, thời gian và đối tượng.'], reviewSuggestions: ['Ôn yếu tố vật lí, hóa học và nguyên tắc dùng kháng sinh.'] },
  { id: 'bio10-m6-s033', questionId: 'bio10-m6-q033', recognition: 'Dạng yếu tố ảnh hưởng và kiểm soát: phân tích tác động của nhiệt độ, pH, độ ẩm, hóa chất hoặc kháng sinh.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Ngừng kháng sinh tùy ý có nguy cơ gì?” thuộc dạng yếu tố ảnh hưởng và kiểm soát: phân tích tác động của nhiệt độ, pH, độ ẩm, hóa chất hoặc kháng sinh.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Tế bào sống sót tiếp tục phát triển và chọn lọc kháng thuốc”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Kháng sinh không điều trị virus; hiệu quả kiểm soát phụ thuộc nồng độ, thời gian và đối tượng.'], reviewSuggestions: ['Ôn yếu tố vật lí, hóa học và nguyên tắc dùng kháng sinh.'] },
  { id: 'bio10-m6-s034', questionId: 'bio10-m6-q034', recognition: 'Dạng sinh trưởng quần thể: nhận diện pha dựa vào tốc độ phân chia, số tế bào sinh và số tế bào chết.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Quần thể phân đôi mỗi 20 phút, từ 100 tế bào sau 60 phút lí tưởng có bao nhiêu?” thuộc dạng sinh trưởng quần thể: nhận diện pha dựa vào tốc độ phân chia, số tế bào sinh và số tế bào chết.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “800”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Pha cân bằng vẫn có tế bào sinh và chết; số lượng ổn định không có nghĩa mọi hoạt động dừng lại.'], reviewSuggestions: ['Ôn bốn pha sinh trưởng trong nuôi cấy không liên tục.'] },
  { id: 'bio10-m6-s035', questionId: 'bio10-m6-q035', recognition: 'Dạng yếu tố ảnh hưởng và kiểm soát: phân tích tác động của nhiệt độ, pH, độ ẩm, hóa chất hoặc kháng sinh.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Chất khử khuẩn chọn lọc tế bào kháng có nghĩa gì?” thuộc dạng yếu tố ảnh hưởng và kiểm soát: phân tích tác động của nhiệt độ, pH, độ ẩm, hóa chất hoặc kháng sinh.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Biến dị kháng có sẵn sống sót và tăng tỉ lệ”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Kháng sinh không điều trị virus; hiệu quả kiểm soát phụ thuộc nồng độ, thời gian và đối tượng.'], reviewSuggestions: ['Ôn yếu tố vật lí, hóa học và nguyên tắc dùng kháng sinh.'] },
  { id: 'bio10-m6-s036', questionId: 'bio10-m6-q036', recognition: 'Dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Sữa chua hình thành nhờ quá trình chính nào?” thuộc dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Vi khuẩn lactic chuyển đường thành acid lactic”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Ứng dụng có ích vẫn cần kiểm soát giống, vệ sinh, nhiệt độ, pH và thời gian.'], reviewSuggestions: ['Ôn ứng dụng lên men, nông nghiệp, thực phẩm và xử lí môi trường.'] },
  { id: 'bio10-m6-s037', questionId: 'bio10-m6-q037', recognition: 'Dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Bánh mì nở nhờ sản phẩm nào của nấm men?” thuộc dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “CO2”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Ứng dụng có ích vẫn cần kiểm soát giống, vệ sinh, nhiệt độ, pH và thời gian.'], reviewSuggestions: ['Ôn ứng dụng lên men, nông nghiệp, thực phẩm và xử lí môi trường.'] },
  { id: 'bio10-m6-s038', questionId: 'bio10-m6-q038', recognition: 'Dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Muối dưa cần nồng độ muối phù hợp để làm gì?” thuộc dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Ưu tiên vi khuẩn lactic và hạn chế nhiều vi sinh vật hỏng”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không nếm mẫu có dấu hiệu nhiễm; một thí nghiệm chỉ nên thay đổi biến đang khảo sát.'], reviewSuggestions: ['Ôn thiết kế thí nghiệm, đối chứng và an toàn sinh học.'] },
  { id: 'bio10-m6-s039', questionId: 'bio10-m6-q039', recognition: 'Dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Xử lí nước thải bằng vi sinh vật dựa trên gì?” thuộc dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Phân giải chất hữu cơ và chuyển hóa chất ô nhiễm”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Ứng dụng có ích vẫn cần kiểm soát giống, vệ sinh, nhiệt độ, pH và thời gian.'], reviewSuggestions: ['Ôn ứng dụng lên men, nông nghiệp, thực phẩm và xử lí môi trường.'] },
  { id: 'bio10-m6-s040', questionId: 'bio10-m6-q040', recognition: 'Dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Phân bón vi sinh có thể hỗ trợ cây bằng cách nào?” thuộc dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Cố định nitrogen hoặc huy động dinh dưỡng”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Ứng dụng có ích vẫn cần kiểm soát giống, vệ sinh, nhiệt độ, pH và thời gian.'], reviewSuggestions: ['Ôn ứng dụng lên men, nông nghiệp, thực phẩm và xử lí môi trường.'] },
  { id: 'bio10-m6-s041', questionId: 'bio10-m6-q041', recognition: 'Dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Sản xuất kháng sinh công nghiệp cần kiểm soát gì?” thuộc dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Giống, môi trường, pH, nhiệt độ và thời điểm thu”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Ứng dụng có ích vẫn cần kiểm soát giống, vệ sinh, nhiệt độ, pH và thời gian.'], reviewSuggestions: ['Ôn ứng dụng lên men, nông nghiệp, thực phẩm và xử lí môi trường.'] },
  { id: 'bio10-m6-s042', questionId: 'bio10-m6-q042', recognition: 'Dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Dự án lên men cần nhóm đối chứng nào hữu ích?” thuộc dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Mẫu giống quy trình nhưng không bổ sung giống hoạt động”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không nếm mẫu có dấu hiệu nhiễm; một thí nghiệm chỉ nên thay đổi biến đang khảo sát.'], reviewSuggestions: ['Ôn thiết kế thí nghiệm, đối chứng và an toàn sinh học.'] },
  { id: 'bio10-m6-s043', questionId: 'bio10-m6-q043', recognition: 'Dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Chỉ tiêu theo dõi lên men lactic phù hợp?” thuộc dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “pH giảm theo thời gian cùng mùi/trạng thái an toàn”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không nếm mẫu có dấu hiệu nhiễm; một thí nghiệm chỉ nên thay đổi biến đang khảo sát.'], reviewSuggestions: ['Ôn thiết kế thí nghiệm, đối chứng và an toàn sinh học.'] },
  { id: 'bio10-m6-s044', questionId: 'bio10-m6-q044', recognition: 'Dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Sản phẩm lên men có mốc lạ, mùi thối nên làm gì?” thuộc dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Loại bỏ an toàn, không nếm thử”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không nếm mẫu có dấu hiệu nhiễm; một thí nghiệm chỉ nên thay đổi biến đang khảo sát.'], reviewSuggestions: ['Ôn thiết kế thí nghiệm, đối chứng và an toàn sinh học.'] },
  { id: 'bio10-m6-s045', questionId: 'bio10-m6-q045', recognition: 'Dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Hai mẻ khác cả nhiệt độ và lượng giống, không thể quy kết khác biệt cho gì?” thuộc dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Một yếu tố riêng lẻ”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không nếm mẫu có dấu hiệu nhiễm; một thí nghiệm chỉ nên thay đổi biến đang khảo sát.'], reviewSuggestions: ['Ôn thiết kế thí nghiệm, đối chứng và an toàn sinh học.'] },
  { id: 'bio10-m6-s046', questionId: 'bio10-m6-q046', recognition: 'Dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Vì sao cần ghi thời gian–nhiệt độ trong nhật kí dự án?” thuộc dạng thực hành và an toàn sinh học: xác định biến, đối chứng, chỉ số theo dõi và cách xử lí mẫu nhiễm.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Để liên hệ điều kiện với tốc độ và chất lượng, tái lập quy trình”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không nếm mẫu có dấu hiệu nhiễm; một thí nghiệm chỉ nên thay đổi biến đang khảo sát.'], reviewSuggestions: ['Ôn thiết kế thí nghiệm, đối chứng và an toàn sinh học.'] },
  { id: 'bio10-m6-s047', questionId: 'bio10-m6-q047', recognition: 'Dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Ưu điểm công nghệ vi sinh so tổng hợp hóa học trong một số sản phẩm?” thuộc dạng ứng dụng vi sinh vật: nối vi sinh vật, cơ chất, sản phẩm và điều kiện của quy trình sản xuất hoặc xử lí môi trường.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Có thể hoạt động điều kiện nhẹ và tạo sản phẩm chọn lọc”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Ứng dụng có ích vẫn cần kiểm soát giống, vệ sinh, nhiệt độ, pH và thời gian.'], reviewSuggestions: ['Ôn ứng dụng lên men, nông nghiệp, thực phẩm và xử lí môi trường.'] },
  { id: 'bio10-m6-sol-st40-st1-e01', questionId: 'bio10-m6-qt40-st1-e01', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Vi sinh vật tiết enzyme ngoại bào chủ yếu để làm gì?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Phân giải phân tử lớn ngoài tế bào thành chất có thể hấp thu”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-e02', questionId: 'bio10-m6-qt40-st1-e02', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Quá trình phân giải glucose để giải phóng năng lượng thuộc nhóm nào?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Dị hóa”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-e03', questionId: 'bio10-m6-qt40-st1-e03', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Tổng hợp protein từ amino acid là ví dụ của quá trình nào?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Đồng hóa”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-m01', questionId: 'bio10-m6-qt40-st1-m01', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Vi khuẩn tạo vòng trong suốt quanh khuẩn lạc trên môi trường chứa tinh bột sau khi thêm iodine. Kết luận hợp lí nhất là gì?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Vi khuẩn tiết enzyme phân giải tinh bột quanh khuẩn lạc”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-m02', questionId: 'bio10-m6-qt40-st1-m02', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Trong môi trường sữa, vùng trong quanh khuẩn lạc tăng dần. Dữ kiện này hỗ trợ nhận định nào?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Vi sinh vật có hoạt tính protease phân giải protein sữa”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-m03', questionId: 'bio10-m6-qt40-st1-m03', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Khi quần thể vi khuẩn tăng sinh khối, quan hệ giữa đồng hóa và dị hóa phù hợp nhất là gì?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Dị hóa cung cấp năng lượng/chất trung gian cho đồng hóa tạo vật chất tế bào”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-m04', questionId: 'bio10-m6-qt40-st1-m04', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Một chủng dùng acetate làm nguồn carbon nhưng không dùng cellulose nguyên vẹn. Giải thích hợp lí nhất là gì?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Chủng có thể hấp thu acetate nhưng thiếu enzyme ngoại bào phân giải cellulose”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-h01', questionId: 'bio10-m6-qt40-st1-h01', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Suy luận phù hợp nhất về chủng Q là gì?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Q có thể thiếu protein cần cho sử dụng lactose nhưng vẫn sử dụng glucose”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-h02', questionId: 'bio10-m6-qt40-st1-h02', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Đột biến làm mất enzyme đầu tiên của một con đường tổng hợp amino acid. Bổ sung chất nào có khả năng phục hồi sinh trưởng trực tiếp nhất?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Amino acid là sản phẩm cuối của con đường”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-h03', questionId: 'bio10-m6-qt40-st1-h03', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Diễn giải nào phù hợp nhất?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Vi sinh vật đã chuyển một phần chất hữu cơ thành năng lượng và sinh khối”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st1-h04', questionId: 'bio10-m6-qt40-st1-h04', recognition: 'Dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Chủng R chỉ phân giải được chất ô nhiễm X khi môi trường có thêm glucose. Kết luận thận trọng nhất là gì?” thuộc dạng chuyển hóa vi sinh vật: xác định cơ chất, enzyme, sản phẩm và chiều đồng hóa hoặc dị hóa.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Phân giải X có thể là đồng chuyển hóa và phụ thuộc năng lượng/chất khử từ glucose”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không đồng nhất phân giải ngoại bào với hấp thu, hoặc cho rằng đồng hóa và dị hóa không liên hệ.'], reviewSuggestions: ['Ôn sơ đồ cơ chất → enzyme → sản phẩm và quan hệ dị hóa–đồng hóa.'] },
  { id: 'bio10-m6-sol-st40-st3-e01', questionId: 'bio10-m6-qt40-st3-e01', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Trong phân đôi của vi khuẩn, sự kiện nào xảy ra trước khi tế bào tách thành hai?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “DNA được sao chép và hai bản phân bố về hai vùng tế bào”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-st40-st3-e02', questionId: 'bio10-m6-qt40-st3-e02', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Nảy chồi ở nấm men tạo tế bào mới bằng cách nào?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Một chồi hình thành, lớn lên và tách khỏi tế bào mẹ”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-st40-st3-e03', questionId: 'bio10-m6-qt40-st3-e03', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Nhận định nào đúng về nội bào tử của một số vi khuẩn?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Chủ yếu là cấu trúc tồn tại, không phải hình thức tăng số lượng tế bào”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-st40-st3-m01', questionId: 'bio10-m6-qt40-st3-m01', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Điểm khác biệt dễ nhận thấy giữa phân đôi vi khuẩn và nảy chồi nấm men là gì?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Nảy chồi thường tạo phần con ban đầu nhỏ hơn tế bào mẹ”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-st40-st3-m02', questionId: 'bio10-m6-qt40-st3-m02', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Một quần thể vi khuẩn có thời gian thế hệ 30 phút. Trong điều kiện lí tưởng, sau 2 giờ đã trải qua bao nhiêu thế hệ?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “4”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-st40-st3-m03', questionId: 'bio10-m6-qt40-st3-m03', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Bào tử vô tính của nấm khác nội bào tử vi khuẩn chủ yếu ở điểm nào?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Bào tử nấm có thể phát tán và tạo cá thể mới, còn nội bào tử vi khuẩn chủ yếu giúp tồn tại”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-st40-st3-h01', questionId: 'bio10-m6-qt40-st3-h01', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Từ 250 tế bào vi khuẩn, sau 5 thế hệ phân đôi lí tưởng có bao nhiêu tế bào?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “8 000”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-st40-st3-h02', questionId: 'bio10-m6-qt40-st3-h02', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Nếu cả hai quần thể đang tăng theo phân đôi lí tưởng, nhận định nào đúng?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “P trải qua 3 thế hệ, Q trải qua 2 thế hệ”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-st40-st3-h03', questionId: 'bio10-m6-qt40-st3-h03', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Một thuốc ức chế hình thành vách ngăn nhưng không chặn sao chép DNA ở vi khuẩn. Quan sát dự kiến là gì?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Tế bào kéo dài hoặc có nhiều bản DNA nhưng khó tách thành tế bào con”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-st40-st3-h04', questionId: 'bio10-m6-qt40-st3-h04', recognition: 'Dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Hai vi khuẩn truyền plasmid cho nhau bằng tiếp hợp. Vì sao không nên gọi đây là sinh sản?” thuộc dạng sinh sản vi sinh vật: nhận diện phân đôi, nảy chồi hoặc tạo bào tử từ diễn biến cấu trúc và số tế bào.' }, { order: 2, title: 'Xử lí dữ kiện', explanation: 'Xác định đối tượng, điều kiện và quan hệ nhân–quả; loại các phương án trái với dữ kiện hoặc bản chất sinh học.' }, { order: 3, title: 'Kết luận', explanation: 'Kết luận phù hợp là “Không làm tăng trực tiếp số lượng cá thể; đây là trao đổi vật chất di truyền”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không coi nội bào tử vi khuẩn là hình thức sinh sản làm tăng số lượng cá thể.'], reviewSuggestions: ['So sánh phân đôi, nảy chồi, tạo bào tử sinh sản và nội bào tử.'] },
  { id: 'bio10-m6-sol-qt7-st1-e01', questionId: 'bio10-m6-qt7-st1-e01', recognition: 'Dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Đặc điểm nào thường khiến nhiều vi sinh vật phải được quan sát bằng kính hiển vi?” thuộc dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.' }, { order: 2, title: 'Quy trình giải', explanation: 'Tách dấu hiệu thành ba tầng: có hay không có cấu tạo tế bào; nhân sơ hay nhân thực; sau đó mới dùng thành tế bào, vận động và sinh sản để thu hẹp nhóm.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Kích thước rất nhỏ”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không đồng nhất vi sinh vật với vi khuẩn và không dùng một dấu hiệu hình thái để khẳng định tên loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st1-m01', questionId: 'bio10-m6-qt7-st1-m01', recognition: 'Dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Nhóm nào gồm tế bào nhân sơ?” thuộc dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.' }, { order: 2, title: 'Quy trình giải', explanation: 'Tách dấu hiệu thành ba tầng: có hay không có cấu tạo tế bào; nhân sơ hay nhân thực; sau đó mới dùng thành tế bào, vận động và sinh sản để thu hẹp nhóm.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Vi khuẩn”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không đồng nhất vi sinh vật với vi khuẩn và không dùng một dấu hiệu hình thái để khẳng định tên loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st1-m02', questionId: 'bio10-m6-qt7-st1-m02', recognition: 'Dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Virus khác vi khuẩn cơ bản ở điểm nào?” thuộc dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.' }, { order: 2, title: 'Quy trình giải', explanation: 'Tách dấu hiệu thành ba tầng: có hay không có cấu tạo tế bào; nhân sơ hay nhân thực; sau đó mới dùng thành tế bào, vận động và sinh sản để thu hẹp nhóm.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Virus không có cấu tạo tế bào và phụ thuộc tế bào chủ để nhân lên”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không đồng nhất vi sinh vật với vi khuẩn và không dùng một dấu hiệu hình thái để khẳng định tên loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st1-m03', questionId: 'bio10-m6-qt7-st1-m03', recognition: 'Dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Tỉ lệ diện tích bề mặt/thể tích lớn ở tế bào vi sinh vật thường có lợi gì?” thuộc dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.' }, { order: 2, title: 'Quy trình giải', explanation: 'Tách dấu hiệu thành ba tầng: có hay không có cấu tạo tế bào; nhân sơ hay nhân thực; sau đó mới dùng thành tế bào, vận động và sinh sản để thu hẹp nhóm.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Hỗ trợ trao đổi chất nhanh với môi trường”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không đồng nhất vi sinh vật với vi khuẩn và không dùng một dấu hiệu hình thái để khẳng định tên loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st1-m04', questionId: 'bio10-m6-qt7-st1-m04', recognition: 'Dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Phát biểu nào đúng nhất về tốc độ sinh trưởng của vi sinh vật?” thuộc dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.' }, { order: 2, title: 'Quy trình giải', explanation: 'Tách dấu hiệu thành ba tầng: có hay không có cấu tạo tế bào; nhân sơ hay nhân thực; sau đó mới dùng thành tế bào, vận động và sinh sản để thu hẹp nhóm.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Có thể rất nhanh khi điều kiện phù hợp, nhưng phụ thuộc loài và môi trường”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không đồng nhất vi sinh vật với vi khuẩn và không dùng một dấu hiệu hình thái để khẳng định tên loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st1-h01', questionId: 'bio10-m6-qt7-st1-h01', recognition: 'Dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Ghép mẫu với nhóm phù hợp nhất là gì?” thuộc dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.' }, { order: 2, title: 'Quy trình giải', explanation: 'Tách dấu hiệu thành ba tầng: có hay không có cấu tạo tế bào; nhân sơ hay nhân thực; sau đó mới dùng thành tế bào, vận động và sinh sản để thu hẹp nhóm.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “P–vi khuẩn; Q–nấm men; R–động vật nguyên sinh”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không đồng nhất vi sinh vật với vi khuẩn và không dùng một dấu hiệu hình thái để khẳng định tên loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st1-h02', questionId: 'bio10-m6-qt7-st1-h02', recognition: 'Dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Một sinh vật kích thước 2 µm, không thấy nhân có màng, có ribosome và phân đôi. Kết luận thận trọng nhất?” thuộc dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.' }, { order: 2, title: 'Quy trình giải', explanation: 'Tách dấu hiệu thành ba tầng: có hay không có cấu tạo tế bào; nhân sơ hay nhân thực; sau đó mới dùng thành tế bào, vận động và sinh sản để thu hẹp nhóm.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Dữ kiện phù hợp tế bào nhân sơ; cần thêm kiểm tra để định danh loài”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không đồng nhất vi sinh vật với vi khuẩn và không dùng một dấu hiệu hình thái để khẳng định tên loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st1-h03', questionId: 'bio10-m6-qt7-st1-h03', recognition: 'Dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Một chủng chuyển được giữa hô hấp hiếu khí và lên men tùy oxygen. Điều này minh họa đặc điểm nào?” thuộc dạng nhận diện nhóm vi sinh vật: dựa vào kiểu tế bào, cấu trúc, kích thước, hình thức sinh sản và đặc điểm chuyển hóa.' }, { order: 2, title: 'Quy trình giải', explanation: 'Tách dấu hiệu thành ba tầng: có hay không có cấu tạo tế bào; nhân sơ hay nhân thực; sau đó mới dùng thành tế bào, vận động và sinh sản để thu hẹp nhóm.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Tính linh hoạt chuyển hóa giúp thích nghi với điều kiện thay đổi”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không đồng nhất vi sinh vật với vi khuẩn và không dùng một dấu hiệu hình thái để khẳng định tên loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st2-e01', questionId: 'bio10-m6-qt7-st2-e01', recognition: 'Dạng kiểu dinh dưỡng: phân loại độc lập theo nguồn năng lượng và nguồn carbon.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Thuật ngữ “tự dưỡng” cho biết vi sinh vật chủ yếu dùng nguồn carbon nào?” thuộc dạng kiểu dinh dưỡng: phân loại độc lập theo nguồn năng lượng và nguồn carbon.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định trục năng lượng trước: ánh sáng là quang, phản ứng hóa học là hóa; xác định trục carbon sau: CO₂ là tự dưỡng, chất hữu cơ là dị dưỡng; ghép hai trục để gọi tên.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “CO₂ hoặc carbon vô cơ”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không nhầm nguồn năng lượng với nguồn carbon; ánh sáng không tự động đồng nghĩa với tự dưỡng.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st2-e02', questionId: 'bio10-m6-qt7-st2-e02', recognition: 'Dạng kiểu dinh dưỡng: phân loại độc lập theo nguồn năng lượng và nguồn carbon.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Tiền tố “quang-” trong kiểu dinh dưỡng cho biết nguồn nào?” thuộc dạng kiểu dinh dưỡng: phân loại độc lập theo nguồn năng lượng và nguồn carbon.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định trục năng lượng trước: ánh sáng là quang, phản ứng hóa học là hóa; xác định trục carbon sau: CO₂ là tự dưỡng, chất hữu cơ là dị dưỡng; ghép hai trục để gọi tên.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Nguồn năng lượng là ánh sáng”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không nhầm nguồn năng lượng với nguồn carbon; ánh sáng không tự động đồng nghĩa với tự dưỡng.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st2-m01', questionId: 'bio10-m6-qt7-st2-m01', recognition: 'Dạng kiểu dinh dưỡng: phân loại độc lập theo nguồn năng lượng và nguồn carbon.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Phân loại đúng bốn chủng P, Q, R, S lần lượt là gì?” thuộc dạng kiểu dinh dưỡng: phân loại độc lập theo nguồn năng lượng và nguồn carbon.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định trục năng lượng trước: ánh sáng là quang, phản ứng hóa học là hóa; xác định trục carbon sau: CO₂ là tự dưỡng, chất hữu cơ là dị dưỡng; ghép hai trục để gọi tên.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Quang tự dưỡng, quang dị dưỡng, hóa tự dưỡng, hóa dị dưỡng”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không nhầm nguồn năng lượng với nguồn carbon; ánh sáng không tự động đồng nghĩa với tự dưỡng.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt7-st2-h01', questionId: 'bio10-m6-qt7-st2-h01', recognition: 'Dạng kiểu dinh dưỡng: phân loại độc lập theo nguồn năng lượng và nguồn carbon.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Kết luận nào phù hợp nhất với thí nghiệm?” thuộc dạng kiểu dinh dưỡng: phân loại độc lập theo nguồn năng lượng và nguồn carbon.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định trục năng lượng trước: ánh sáng là quang, phản ứng hóa học là hóa; xác định trục carbon sau: CO₂ là tự dưỡng, chất hữu cơ là dị dưỡng; ghép hai trục để gọi tên.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Trong ánh sáng, chủng cố định CO₂ vào sinh khối, phù hợp kiểu quang tự dưỡng”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không nhầm nguồn năng lượng với nguồn carbon; ánh sáng không tự động đồng nghĩa với tự dưỡng.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st1-e01', questionId: 'bio10-m6-qt39-st1-e01', recognition: 'Dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Khác biệt đúng giữa tiệt trùng và khử khuẩn là gì?” thuộc dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định mục tiêu là tiệt trùng, khử khuẩn hay kiểm tra dinh dưỡng; sau đó chọn đối chứng âm và chỉ thay đổi đúng một biến.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Tiệt trùng nhằm loại bỏ mọi dạng sống vi sinh vật; khử khuẩn làm giảm phần lớn vi sinh vật gây hại trên vật thể”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Đối chứng không cấy xuất hiện khuẩn lạc là dấu hiệu tạp nhiễm, không phải bằng chứng chủng thử nghiệm phát triển.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st1-e02', questionId: 'bio10-m6-qt39-st1-e02', recognition: 'Dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Dụng cụ thủy tinh chịu nhiệt thường được tiệt trùng trong nồi hấp nhờ yếu tố nào?” thuộc dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định mục tiêu là tiệt trùng, khử khuẩn hay kiểm tra dinh dưỡng; sau đó chọn đối chứng âm và chỉ thay đổi đúng một biến.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Hơi nước bão hòa dưới áp suất ở nhiệt độ cao”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Đối chứng không cấy xuất hiện khuẩn lạc là dấu hiệu tạp nhiễm, không phải bằng chứng chủng thử nghiệm phát triển.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st1-m01', questionId: 'bio10-m6-qt39-st1-m01', recognition: 'Dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Vì sao que cấy cần được khử trùng trước và sau khi lấy mẫu?” thuộc dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định mục tiêu là tiệt trùng, khử khuẩn hay kiểm tra dinh dưỡng; sau đó chọn đối chứng âm và chỉ thay đổi đúng một biến.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Tránh đưa tạp nhiễm vào mẫu và phát tán vi sinh vật ra ngoài”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Đối chứng không cấy xuất hiện khuẩn lạc là dấu hiệu tạp nhiễm, không phải bằng chứng chủng thử nghiệm phát triển.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st1-m02', questionId: 'bio10-m6-qt39-st1-m02', recognition: 'Dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Thao tác nào phù hợp nhất để giảm nhiễm khi rót môi trường vô trùng vào đĩa?” thuộc dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định mục tiêu là tiệt trùng, khử khuẩn hay kiểm tra dinh dưỡng; sau đó chọn đối chứng âm và chỉ thay đổi đúng một biến.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Khử khuẩn khu vực, mở nắp vừa đủ và thao tác nhanh gần vùng sạch”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Đối chứng không cấy xuất hiện khuẩn lạc là dấu hiệu tạp nhiễm, không phải bằng chứng chủng thử nghiệm phát triển.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st1-m03', questionId: 'bio10-m6-qt39-st1-m03', recognition: 'Dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Đĩa môi trường không cấy vẫn xuất hiện nhiều khuẩn lạc. Suy luận phù hợp nhất?” thuộc dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định mục tiêu là tiệt trùng, khử khuẩn hay kiểm tra dinh dưỡng; sau đó chọn đối chứng âm và chỉ thay đổi đúng một biến.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Có tạp nhiễm từ môi trường, dụng cụ hoặc thao tác”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Đối chứng không cấy xuất hiện khuẩn lạc là dấu hiệu tạp nhiễm, không phải bằng chứng chủng thử nghiệm phát triển.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st1-m04', questionId: 'bio10-m6-qt39-st1-m04', recognition: 'Dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Muốn kiểm tra một chất dinh dưỡng có cần cho chủng X không, cặp môi trường nào là đối chứng hợp lí?” thuộc dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định mục tiêu là tiệt trùng, khử khuẩn hay kiểm tra dinh dưỡng; sau đó chọn đối chứng âm và chỉ thay đổi đúng một biến.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Hai môi trường giống nhau, chỉ một môi trường thiếu chất đang khảo sát”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Đối chứng không cấy xuất hiện khuẩn lạc là dấu hiệu tạp nhiễm, không phải bằng chứng chủng thử nghiệm phát triển.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st1-h01', questionId: 'bio10-m6-qt39-st1-h01', recognition: 'Dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Kết luận nào được bảng hỗ trợ tốt nhất?” thuộc dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định mục tiêu là tiệt trùng, khử khuẩn hay kiểm tra dinh dưỡng; sau đó chọn đối chứng âm và chỉ thay đổi đúng một biến.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Q ở nồng độ cao làm giảm khuẩn lạc mạnh nhất trong điều kiện thử nghiệm”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Đối chứng không cấy xuất hiện khuẩn lạc là dấu hiệu tạp nhiễm, không phải bằng chứng chủng thử nghiệm phát triển.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st1-h02', questionId: 'bio10-m6-qt39-st1-h02', recognition: 'Dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Ba đĩa đều nhiễm, kể cả đối chứng không mở nắp; nhưng lô môi trường khác cùng ngày không nhiễm. Nguồn lỗi nên kiểm tra trước?” thuộc dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định mục tiêu là tiệt trùng, khử khuẩn hay kiểm tra dinh dưỡng; sau đó chọn đối chứng âm và chỉ thay đổi đúng một biến.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Quy trình tiệt trùng hoặc bảo quản của chính lô môi trường bị nhiễm”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Đối chứng không cấy xuất hiện khuẩn lạc là dấu hiệu tạp nhiễm, không phải bằng chứng chủng thử nghiệm phát triển.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st1-h03', questionId: 'bio10-m6-qt39-st1-h03', recognition: 'Dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Dung dịch chứa protein nhạy nhiệt cần loại vi khuẩn mà không làm biến tính protein. Phương án phù hợp nhất?” thuộc dạng vô trùng, môi trường và đối chứng: tìm nguồn tạp nhiễm, biến khảo sát và điều kiện phải giữ cố định.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định mục tiêu là tiệt trùng, khử khuẩn hay kiểm tra dinh dưỡng; sau đó chọn đối chứng âm và chỉ thay đổi đúng một biến.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Lọc vô trùng qua màng có kích thước lỗ phù hợp”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Đối chứng không cấy xuất hiện khuẩn lạc là dấu hiệu tạp nhiễm, không phải bằng chứng chủng thử nghiệm phát triển.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st2-e01', questionId: 'bio10-m6-qt39-st2-e01', recognition: 'Dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Chỉ dựa vào màu và hình dạng khuẩn lạc có thể khẳng định chắc chắn tên loài không?” thuộc dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.' }, { order: 2, title: 'Quy trình giải', explanation: 'Phân biệt ba mức kết luận: khuẩn lạc tách biệt, dòng nuôi tương đối thuần và định danh loài; mỗi mức cần bằng chứng tăng dần.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Không; cần kết hợp thêm đặc điểm tế bào, sinh hóa hoặc phân tử”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Khuẩn lạc riêng chưa chắc bắt đầu từ đúng một tế bào và hình thái giống nhau chưa đủ khẳng định cùng loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st2-m01', questionId: 'bio10-m6-qt39-st2-m01', recognition: 'Dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Vì sao cấy ria qua nhiều vùng trên đĩa có thể tạo khuẩn lạc riêng?” thuộc dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.' }, { order: 2, title: 'Quy trình giải', explanation: 'Phân biệt ba mức kết luận: khuẩn lạc tách biệt, dòng nuôi tương đối thuần và định danh loài; mỗi mức cần bằng chứng tăng dần.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Pha loãng cơ học số tế bào qua mỗi vùng ria”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Khuẩn lạc riêng chưa chắc bắt đầu từ đúng một tế bào và hình thái giống nhau chưa đủ khẳng định cùng loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st2-m02', questionId: 'bio10-m6-qt39-st2-m02', recognition: 'Dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Sau khi lấy một khuẩn lạc riêng, bước nào giúp kiểm tra dòng thuần tốt hơn?” thuộc dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.' }, { order: 2, title: 'Quy trình giải', explanation: 'Phân biệt ba mức kết luận: khuẩn lạc tách biệt, dòng nuôi tương đối thuần và định danh loài; mỗi mức cần bằng chứng tăng dần.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Cấy lại và kiểm tra tính đồng nhất bằng nhiều dấu hiệu phù hợp”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Khuẩn lạc riêng chưa chắc bắt đầu từ đúng một tế bào và hình thái giống nhau chưa đủ khẳng định cùng loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st2-m03', questionId: 'bio10-m6-qt39-st2-m03', recognition: 'Dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Môi trường chọn lọc và môi trường phân biệt khác nhau chủ yếu thế nào?” thuộc dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.' }, { order: 2, title: 'Quy trình giải', explanation: 'Phân biệt ba mức kết luận: khuẩn lạc tách biệt, dòng nuôi tương đối thuần và định danh loài; mỗi mức cần bằng chứng tăng dần.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Chọn lọc ức chế/ưu tiên nhóm; phân biệt làm lộ đặc điểm chuyển hóa giữa các nhóm mọc được”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Khuẩn lạc riêng chưa chắc bắt đầu từ đúng một tế bào và hình thái giống nhau chưa đủ khẳng định cùng loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st2-m04', questionId: 'bio10-m6-qt39-st2-m04', recognition: 'Dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Một khuẩn lạc được cấy lại nhưng đĩa mới xuất hiện hai kiểu khuẩn lạc ổn định. Giải thích hợp lí nhất?” thuộc dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.' }, { order: 2, title: 'Quy trình giải', explanation: 'Phân biệt ba mức kết luận: khuẩn lạc tách biệt, dòng nuôi tương đối thuần và định danh loài; mỗi mức cần bằng chứng tăng dần.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Khuẩn lạc ban đầu có thể lẫn tế bào hoặc thao tác bị nhiễm”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Khuẩn lạc riêng chưa chắc bắt đầu từ đúng một tế bào và hình thái giống nhau chưa đủ khẳng định cùng loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st2-h01', questionId: 'bio10-m6-qt39-st2-h01', recognition: 'Dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Mẫu X phù hợp nhất với chủng tham chiếu nào?” thuộc dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.' }, { order: 2, title: 'Quy trình giải', explanation: 'Phân biệt ba mức kết luận: khuẩn lạc tách biệt, dòng nuôi tương đối thuần và định danh loài; mỗi mức cần bằng chứng tăng dần.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “P”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Khuẩn lạc riêng chưa chắc bắt đầu từ đúng một tế bào và hình thái giống nhau chưa đủ khẳng định cùng loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st2-h02', questionId: 'bio10-m6-qt39-st2-h02', recognition: 'Dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Đĩa cấy ria có ba kiểu khuẩn lạc. Muốn phân lập từng dòng, quy trình nào hợp lí nhất?” thuộc dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.' }, { order: 2, title: 'Quy trình giải', explanation: 'Phân biệt ba mức kết luận: khuẩn lạc tách biệt, dòng nuôi tương đối thuần và định danh loài; mỗi mức cần bằng chứng tăng dần.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Chọn một khuẩn lạc tách biệt của từng kiểu, cấy lại riêng và kiểm tra độ thuần”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Khuẩn lạc riêng chưa chắc bắt đầu từ đúng một tế bào và hình thái giống nhau chưa đủ khẳng định cùng loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st2-h03', questionId: 'bio10-m6-qt39-st2-h03', recognition: 'Dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Hai chủng có hình dạng tế bào và màu khuẩn lạc giống nhau. Dữ liệu nào giúp phân biệt đáng tin cậy hơn?” thuộc dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.' }, { order: 2, title: 'Quy trình giải', explanation: 'Phân biệt ba mức kết luận: khuẩn lạc tách biệt, dòng nuôi tương đối thuần và định danh loài; mỗi mức cần bằng chứng tăng dần.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Tổ hợp thử nghiệm sinh hóa hoặc dấu ấn phân tử có đối chứng”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Khuẩn lạc riêng chưa chắc bắt đầu từ đúng một tế bào và hình thái giống nhau chưa đủ khẳng định cùng loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st2-h04', questionId: 'bio10-m6-qt39-st2-h04', recognition: 'Dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Kính hiển vi thấy mẫu chỉ có trực khuẩn đồng đều. Vì sao chưa đủ khẳng định dòng thuần?” thuộc dạng phân lập và nhận diện: theo dõi cấy ria, chọn khuẩn lạc riêng, kiểm tra dòng thuần và định danh bằng nhiều bằng chứng.' }, { order: 2, title: 'Quy trình giải', explanation: 'Phân biệt ba mức kết luận: khuẩn lạc tách biệt, dòng nuôi tương đối thuần và định danh loài; mỗi mức cần bằng chứng tăng dần.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Nhiều loài có thể cùng hình dạng; cần thêm bằng chứng nuôi cấy và đặc trưng khác”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Khuẩn lạc riêng chưa chắc bắt đầu từ đúng một tế bào và hình thái giống nhau chưa đủ khẳng định cùng loài.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st3-e01', questionId: 'bio10-m6-qt39-st3-e01', recognition: 'Dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Trộn 1 mL mẫu với 9 mL dung môi vô trùng tạo độ pha loãng nào?” thuộc dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Dùng CFU/mL = số khuẩn lạc / (thể tích cấy × độ pha loãng). Với đĩa lặp hợp lệ, lấy trung bình số khuẩn lạc rồi mới thay số và kiểm tra đơn vị.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “10⁻¹”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không quên hệ số thể tích 0,1 mL và không dùng đĩa khuẩn lạc chồng lấp để tính chính xác.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st3-e02', questionId: 'bio10-m6-qt39-st3-e02', recognition: 'Dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Công thức tính mật độ mẫu gốc phù hợp là gì?” thuộc dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Dùng CFU/mL = số khuẩn lạc / (thể tích cấy × độ pha loãng). Với đĩa lặp hợp lệ, lấy trung bình số khuẩn lạc rồi mới thay số và kiểm tra đơn vị.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “CFU/mL = số khuẩn lạc / (thể tích cấy × độ pha loãng)”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không quên hệ số thể tích 0,1 mL và không dùng đĩa khuẩn lạc chồng lấp để tính chính xác.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st3-e03', questionId: 'bio10-m6-qt39-st3-e03', recognition: 'Dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Trong thực hành đếm khuẩn lạc, đĩa nào thường phù hợp hơn để định lượng?” thuộc dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Dùng CFU/mL = số khuẩn lạc / (thể tích cấy × độ pha loãng). Với đĩa lặp hợp lệ, lấy trung bình số khuẩn lạc rồi mới thay số và kiểm tra đơn vị.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Đĩa có số khuẩn lạc tách biệt trong khoảng đếm quy ước”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không quên hệ số thể tích 0,1 mL và không dùng đĩa khuẩn lạc chồng lấp để tính chính xác.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st3-m01', questionId: 'bio10-m6-qt39-st3-m01', recognition: 'Dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Cấy 1 mL mẫu pha loãng 10⁻³ thu được 120 khuẩn lạc. Mật độ mẫu gốc là bao nhiêu?” thuộc dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Dùng CFU/mL = số khuẩn lạc / (thể tích cấy × độ pha loãng). Với đĩa lặp hợp lệ, lấy trung bình số khuẩn lạc rồi mới thay số và kiểm tra đơn vị.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “1,2 × 10⁵ CFU/mL”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không quên hệ số thể tích 0,1 mL và không dùng đĩa khuẩn lạc chồng lấp để tính chính xác.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st3-m02', questionId: 'bio10-m6-qt39-st3-m02', recognition: 'Dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Cấy 0,1 mL mẫu pha loãng 10⁻⁴ thu được 45 khuẩn lạc. Mật độ mẫu gốc là bao nhiêu?” thuộc dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Dùng CFU/mL = số khuẩn lạc / (thể tích cấy × độ pha loãng). Với đĩa lặp hợp lệ, lấy trung bình số khuẩn lạc rồi mới thay số và kiểm tra đơn vị.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “4,5 × 10⁶ CFU/mL”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không quên hệ số thể tích 0,1 mL và không dùng đĩa khuẩn lạc chồng lấp để tính chính xác.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt39-st3-h01', questionId: 'bio10-m6-qt39-st3-h01', recognition: 'Dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Dùng trung bình hai đĩa, mật độ mẫu gốc xấp xỉ bao nhiêu?” thuộc dạng pha loãng và CFU: nhận diện độ pha loãng, thể tích cấy và số khuẩn lạc trước khi quy về mẫu gốc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Dùng CFU/mL = số khuẩn lạc / (thể tích cấy × độ pha loãng). Với đĩa lặp hợp lệ, lấy trung bình số khuẩn lạc rồi mới thay số và kiểm tra đơn vị.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “3,4 × 10⁷ CFU/mL”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không quên hệ số thể tích 0,1 mL và không dùng đĩa khuẩn lạc chồng lấp để tính chính xác.'], reviewSuggestions: ['Tự xác định dạng và giải lại không nhìn phương án; với CFU phải ghi đủ công thức và đơn vị.'] }
  ,{ id: 'bio10-m6-sol-qt40-st2-m01', questionId: 'bio10-m6-qt40-st2-m01', recognition: 'Dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Đoạn tăng dốc nhất trên đồ thị tương ứng pha nào?” thuộc dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.' }, { order: 2, title: 'Quy trình giải', explanation: 'Đọc trục và xu hướng trước; khi tính dùng n = thời gian/thời gian thế hệ và N = N₀ × 2ⁿ. Phân biệt độ đục tổng với CFU tế bào sống.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Lũy thừa”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Pha cân bằng không có nghĩa mọi tế bào ngừng hoạt động; OD cao không chứng minh số tế bào sống còn cao.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st2-m02', questionId: 'bio10-m6-qt40-st2-m02', recognition: 'Dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Quần thể tăng từ 10³ lên 8 × 10³ tế bào. Quần thể đã trải qua bao nhiêu thế hệ phân đôi?” thuộc dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.' }, { order: 2, title: 'Quy trình giải', explanation: 'Đọc trục và xu hướng trước; khi tính dùng n = thời gian/thời gian thế hệ và N = N₀ × 2ⁿ. Phân biệt độ đục tổng với CFU tế bào sống.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “3”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Pha cân bằng không có nghĩa mọi tế bào ngừng hoạt động; OD cao không chứng minh số tế bào sống còn cao.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st2-m03', questionId: 'bio10-m6-qt40-st2-m03', recognition: 'Dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Nuôi cấy liên tục khác nuôi cấy không liên tục chủ yếu ở điểm nào?” thuộc dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.' }, { order: 2, title: 'Quy trình giải', explanation: 'Đọc trục và xu hướng trước; khi tính dùng n = thời gian/thời gian thế hệ và N = N₀ × 2ⁿ. Phân biệt độ đục tổng với CFU tế bào sống.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Có bổ sung môi trường mới và lấy bớt dịch nuôi để duy trì trạng thái mong muốn”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Pha cân bằng không có nghĩa mọi tế bào ngừng hoạt động; OD cao không chứng minh số tế bào sống còn cao.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st2-m04', questionId: 'bio10-m6-qt40-st2-m04', recognition: 'Dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Khi chuyển giống đang hoạt động sang môi trường mới có thành phần rất khác, pha tiềm phát có thể dài hơn vì sao?” thuộc dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.' }, { order: 2, title: 'Quy trình giải', explanation: 'Đọc trục và xu hướng trước; khi tính dùng n = thời gian/thời gian thế hệ và N = N₀ × 2ⁿ. Phân biệt độ đục tổng với CFU tế bào sống.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Tế bào cần điều chỉnh biểu hiện gene và tổng hợp enzyme thích hợp”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Pha cân bằng không có nghĩa mọi tế bào ngừng hoạt động; OD cao không chứng minh số tế bào sống còn cao.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st2-h01', questionId: 'bio10-m6-qt40-st2-h01', recognition: 'Dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Một quần thể ban đầu có 5 × 10² tế bào, thời gian thế hệ 30 phút. Sau 3 giờ lí tưởng có bao nhiêu tế bào?” thuộc dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.' }, { order: 2, title: 'Quy trình giải', explanation: 'Đọc trục và xu hướng trước; khi tính dùng n = thời gian/thời gian thế hệ và N = N₀ × 2ⁿ. Phân biệt độ đục tổng với CFU tế bào sống.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “3,2 × 10⁴”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Pha cân bằng không có nghĩa mọi tế bào ngừng hoạt động; OD cao không chứng minh số tế bào sống còn cao.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st2-h02', questionId: 'bio10-m6-qt40-st2-h02', recognition: 'Dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Vì sao ở 18 giờ OD vẫn cao nhưng CFU giảm mạnh?” thuộc dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.' }, { order: 2, title: 'Quy trình giải', explanation: 'Đọc trục và xu hướng trước; khi tính dùng n = thời gian/thời gian thế hệ và N = N₀ × 2ⁿ. Phân biệt độ đục tổng với CFU tế bào sống.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Tế bào chết/mảnh tế bào vẫn góp phần làm đục, còn CFU chỉ phản ánh đơn vị có khả năng tạo khuẩn lạc”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Pha cân bằng không có nghĩa mọi tế bào ngừng hoạt động; OD cao không chứng minh số tế bào sống còn cao.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st2-h03', questionId: 'bio10-m6-qt40-st2-h03', recognition: 'Dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Một chất chuyển hóa thứ cấp được tạo nhiều khi sinh trưởng chậm lại. Thời điểm thu sản phẩm nên ưu tiên?” thuộc dạng đường cong sinh trưởng: xác định pha, thời gian thế hệ, số thế hệ và đại lượng dùng theo dõi quần thể.' }, { order: 2, title: 'Quy trình giải', explanation: 'Đọc trục và xu hướng trước; khi tính dùng n = thời gian/thời gian thế hệ và N = N₀ × 2ⁿ. Phân biệt độ đục tổng với CFU tế bào sống.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Giai đoạn chuyển từ lũy thừa sang cân bằng, sau khi xác nhận đường tạo sản phẩm”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Pha cân bằng không có nghĩa mọi tế bào ngừng hoạt động; OD cao không chứng minh số tế bào sống còn cao.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st4-e01', questionId: 'bio10-m6-qt40-st4-e01', recognition: 'Dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Bảo quản lạnh thường tác động thế nào lên nhiều vi sinh vật gây hỏng?” thuộc dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định yếu tố tác động vào cấu trúc/quá trình nào, đọc đúng đại lượng đo; với MIC chọn nồng độ thấp nhất không còn sinh trưởng quan sát được.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Làm chậm chuyển hóa và sinh trưởng, không nhất thiết tiêu diệt hết”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không coi làm lạnh hay thanh trùng là tiệt trùng; kháng sinh không tạo biến dị kháng theo nhu cầu mà chọn lọc biến dị đã có/phát sinh ngẫu nhiên.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st4-e02', questionId: 'bio10-m6-qt40-st4-e02', recognition: 'Dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Thanh trùng khác tiệt trùng ở điểm nào?” thuộc dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định yếu tố tác động vào cấu trúc/quá trình nào, đọc đúng đại lượng đo; với MIC chọn nồng độ thấp nhất không còn sinh trưởng quan sát được.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Thanh trùng giảm vi sinh vật gây hại/hư hỏng nhưng không nhất thiết loại hết mọi dạng sống”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không coi làm lạnh hay thanh trùng là tiệt trùng; kháng sinh không tạo biến dị kháng theo nhu cầu mà chọn lọc biến dị đã có/phát sinh ngẫu nhiên.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st4-e03', questionId: 'bio10-m6-qt40-st4-e03', recognition: 'Dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Kháng sinh tác động chọn lọc lên vi khuẩn vì thường nhắm tới gì?” thuộc dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định yếu tố tác động vào cấu trúc/quá trình nào, đọc đúng đại lượng đo; với MIC chọn nồng độ thấp nhất không còn sinh trưởng quan sát được.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Cấu trúc hoặc quá trình đặc trưng của vi khuẩn như thành tế bào hay ribosome”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không coi làm lạnh hay thanh trùng là tiệt trùng; kháng sinh không tạo biến dị kháng theo nhu cầu mà chọn lọc biến dị đã có/phát sinh ngẫu nhiên.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st4-m01', questionId: 'bio10-m6-qt40-st4-m01', recognition: 'Dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Thực phẩm có pH thấp thường bảo quản được lâu hơn vì sao?” thuộc dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định yếu tố tác động vào cấu trúc/quá trình nào, đọc đúng đại lượng đo; với MIC chọn nồng độ thấp nhất không còn sinh trưởng quan sát được.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “pH ngoài khoảng tối ưu ức chế hoạt động enzyme và sinh trưởng của nhiều vi sinh vật”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không coi làm lạnh hay thanh trùng là tiệt trùng; kháng sinh không tạo biến dị kháng theo nhu cầu mà chọn lọc biến dị đã có/phát sinh ngẫu nhiên.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st4-m02', questionId: 'bio10-m6-qt40-st4-m02', recognition: 'Dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Muối hoặc đường nồng độ cao giúp bảo quản chủ yếu bằng cơ chế nào?” thuộc dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định yếu tố tác động vào cấu trúc/quá trình nào, đọc đúng đại lượng đo; với MIC chọn nồng độ thấp nhất không còn sinh trưởng quan sát được.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Giảm hoạt độ nước và gây áp suất thẩm thấu bất lợi cho nhiều tế bào”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không coi làm lạnh hay thanh trùng là tiệt trùng; kháng sinh không tạo biến dị kháng theo nhu cầu mà chọn lọc biến dị đã có/phát sinh ngẫu nhiên.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st4-m03', questionId: 'bio10-m6-qt40-st4-m03', recognition: 'Dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Trong cùng điều kiện, chủng nhạy nhất với kháng sinh nào?” thuộc dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định yếu tố tác động vào cấu trúc/quá trình nào, đọc đúng đại lượng đo; với MIC chọn nồng độ thấp nhất không còn sinh trưởng quan sát được.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “P”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không coi làm lạnh hay thanh trùng là tiệt trùng; kháng sinh không tạo biến dị kháng theo nhu cầu mà chọn lọc biến dị đã có/phát sinh ngẫu nhiên.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st4-m04', questionId: 'bio10-m6-qt40-st4-m04', recognition: 'Dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Sau nhiều lần dùng kháng sinh không đúng chỉ định, tần số vi khuẩn kháng tăng. Giải thích đúng nhất?” thuộc dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định yếu tố tác động vào cấu trúc/quá trình nào, đọc đúng đại lượng đo; với MIC chọn nồng độ thấp nhất không còn sinh trưởng quan sát được.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Kháng sinh tạo áp lực chọn lọc, tế bào có biến dị kháng sống và sinh sản nhiều hơn”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không coi làm lạnh hay thanh trùng là tiệt trùng; kháng sinh không tạo biến dị kháng theo nhu cầu mà chọn lọc biến dị đã có/phát sinh ngẫu nhiên.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt40-st4-h01', questionId: 'bio10-m6-qt40-st4-h01', recognition: 'Dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Nồng độ ức chế tối thiểu (MIC) của chất X trong thí nghiệm là bao nhiêu?” thuộc dạng yếu tố môi trường và kháng thuốc: nhận diện tác động ức chế/tiêu diệt, đọc kháng sinh đồ hoặc MIC và giải thích chọn lọc.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định yếu tố tác động vào cấu trúc/quá trình nào, đọc đúng đại lượng đo; với MIC chọn nồng độ thấp nhất không còn sinh trưởng quan sát được.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “2 µg/mL”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không coi làm lạnh hay thanh trùng là tiệt trùng; kháng sinh không tạo biến dị kháng theo nhu cầu mà chọn lọc biến dị đã có/phát sinh ngẫu nhiên.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st1-e01', questionId: 'bio10-m6-qt41-st1-e01', recognition: 'Dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Trong lên men rượu, nấm men chuyển hóa đường chủ yếu tạo sản phẩm nào?” thuộc dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định sản phẩm mong muốn, cơ chế vi sinh vật tạo sản phẩm và nút kiểm soát khi mở rộng quy mô; nếu có nhiều tiêu chí phải tối ưu đồng thời năng suất và độ tinh sạch.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Ethanol và CO₂”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không chọn điều kiện chỉ vì năng suất cao nhất nếu tạp chất, oxygen, nhiệt hoặc an toàn không đạt.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st1-m01', questionId: 'bio10-m6-qt41-st1-m01', recognition: 'Dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Trong xử lí đất ô nhiễm dầu, vai trò phù hợp của vi sinh vật là gì?” thuộc dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định sản phẩm mong muốn, cơ chế vi sinh vật tạo sản phẩm và nút kiểm soát khi mở rộng quy mô; nếu có nhiều tiêu chí phải tối ưu đồng thời năng suất và độ tinh sạch.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Phân giải hoặc chuyển hóa hydrocarbon thành chất ít độc hơn”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không chọn điều kiện chỉ vì năng suất cao nhất nếu tạp chất, oxygen, nhiệt hoặc an toàn không đạt.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st1-m02', questionId: 'bio10-m6-qt41-st1-m02', recognition: 'Dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Vi khuẩn tái tổ hợp có thể sản xuất insulin người nhờ nguyên lí nào?” thuộc dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định sản phẩm mong muốn, cơ chế vi sinh vật tạo sản phẩm và nút kiểm soát khi mở rộng quy mô; nếu có nhiều tiêu chí phải tối ưu đồng thời năng suất và độ tinh sạch.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Đưa gene mã hóa phù hợp vào hệ biểu hiện vi khuẩn để tổng hợp protein”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không chọn điều kiện chỉ vì năng suất cao nhất nếu tạp chất, oxygen, nhiệt hoặc an toàn không đạt.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st1-h01', questionId: 'bio10-m6-qt41-st1-h01', recognition: 'Dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Nếu ưu tiên năng suất cao nhưng tạp chất thấp, điều kiện nào cân bằng hợp lí nhất?” thuộc dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định sản phẩm mong muốn, cơ chế vi sinh vật tạo sản phẩm và nút kiểm soát khi mở rộng quy mô; nếu có nhiều tiêu chí phải tối ưu đồng thời năng suất và độ tinh sạch.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “R”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không chọn điều kiện chỉ vì năng suất cao nhất nếu tạp chất, oxygen, nhiệt hoặc an toàn không đạt.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st1-h02', questionId: 'bio10-m6-qt41-st1-h02', recognition: 'Dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Ưu điểm chính của cố định tế bào vi sinh vật trên giá mang trong một số quy trình là gì?” thuộc dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định sản phẩm mong muốn, cơ chế vi sinh vật tạo sản phẩm và nút kiểm soát khi mở rộng quy mô; nếu có nhiều tiêu chí phải tối ưu đồng thời năng suất và độ tinh sạch.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Có thể giữ và tái sử dụng tế bào, thuận lợi tách sản phẩm”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không chọn điều kiện chỉ vì năng suất cao nhất nếu tạp chất, oxygen, nhiệt hoặc an toàn không đạt.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st1-h03', questionId: 'bio10-m6-qt41-st1-h03', recognition: 'Dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Quy trình lên men tốt ở bình nhỏ nhưng năng suất giảm khi tăng lên bồn lớn. Nguyên nhân cần kiểm tra ưu tiên?” thuộc dạng ứng dụng công nghệ vi sinh vật: nối chủng–cơ chất–sản phẩm với điều kiện quy trình và tiêu chí hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Xác định sản phẩm mong muốn, cơ chế vi sinh vật tạo sản phẩm và nút kiểm soát khi mở rộng quy mô; nếu có nhiều tiêu chí phải tối ưu đồng thời năng suất và độ tinh sạch.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Khả năng khuấy trộn, truyền oxygen và thoát nhiệt không đồng đều khi tăng quy mô”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không chọn điều kiện chỉ vì năng suất cao nhất nếu tạp chất, oxygen, nhiệt hoặc an toàn không đạt.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st2-e01', questionId: 'bio10-m6-qt41-st2-e01', recognition: 'Dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Trong thí nghiệm khảo sát ảnh hưởng nhiệt độ đến lên men, biến độc lập là gì?” thuộc dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Giữ các biến kiểm soát, chỉ thay biến độc lập; đọc pH/trạng thái theo thời gian và loại mọi mẻ có dấu hiệu nhiễm trước khi so năng suất.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Nhiệt độ”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không nếm thử sản phẩm nghi nhiễm và không quy kết nguyên nhân khi hai mẻ khác nhau ở nhiều biến cùng lúc.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st2-e02', questionId: 'bio10-m6-qt41-st2-e02', recognition: 'Dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Dấu hiệu nào yêu cầu loại bỏ mẻ lên men và không nếm thử?” thuộc dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Giữ các biến kiểm soát, chỉ thay biến độc lập; đọc pH/trạng thái theo thời gian và loại mọi mẻ có dấu hiệu nhiễm trước khi so năng suất.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Mốc màu lạ hoặc mùi thối bất thường”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không nếm thử sản phẩm nghi nhiễm và không quy kết nguyên nhân khi hai mẻ khác nhau ở nhiều biến cùng lúc.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st2-m01', questionId: 'bio10-m6-qt41-st2-m01', recognition: 'Dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Muốn khảo sát ảnh hưởng lượng giống, thiết kế nào hợp lí?” thuộc dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Giữ các biến kiểm soát, chỉ thay biến độc lập; đọc pH/trạng thái theo thời gian và loại mọi mẻ có dấu hiệu nhiễm trước khi so năng suất.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Giữ nguyên nguyên liệu, nhiệt độ, thời gian; chỉ thay lượng giống giữa các nhóm”. Vì vậy chọn C.' }], finalAnswer: 'C', commonMistakes: ['Không nếm thử sản phẩm nghi nhiễm và không quy kết nguyên nhân khi hai mẻ khác nhau ở nhiều biến cùng lúc.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st2-m02', questionId: 'bio10-m6-qt41-st2-m02', recognition: 'Dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Dữ liệu nào hỗ trợ tốt nhất rằng lên men lactic đang diễn ra?” thuộc dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Giữ các biến kiểm soát, chỉ thay biến độc lập; đọc pH/trạng thái theo thời gian và loại mọi mẻ có dấu hiệu nhiễm trước khi so năng suất.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “pH giảm cùng trạng thái đặc và mùi chua đặc trưng, không có dấu hiệu nhiễm”. Vì vậy chọn D.' }], finalAnswer: 'D', commonMistakes: ['Không nếm thử sản phẩm nghi nhiễm và không quy kết nguyên nhân khi hai mẻ khác nhau ở nhiều biến cùng lúc.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st2-m03', questionId: 'bio10-m6-qt41-st2-m03', recognition: 'Dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Vì sao mỗi điều kiện nên làm nhiều mẻ lặp?” thuộc dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Giữ các biến kiểm soát, chỉ thay biến độc lập; đọc pH/trạng thái theo thời gian và loại mọi mẻ có dấu hiệu nhiễm trước khi so năng suất.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “Ước lượng biến thiên và giảm ảnh hưởng của sai số ngẫu nhiên”. Vì vậy chọn A.' }], finalAnswer: 'A', commonMistakes: ['Không nếm thử sản phẩm nghi nhiễm và không quy kết nguyên nhân khi hai mẻ khác nhau ở nhiều biến cùng lúc.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
  ,{ id: 'bio10-m6-sol-qt41-st2-h01', questionId: 'bio10-m6-qt41-st2-h01', recognition: 'Dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.', detailedSteps: [{ order: 1, title: 'Dấu hiệu nhận dạng', explanation: 'Câu hỏi “Nếu yêu cầu trước hết phải an toàn, sau đó mới tối ưu hiệu suất, nên chọn mẻ nào?” thuộc dạng dự án lên men: xác định biến, đối chứng, chỉ số theo dõi, độ lặp và ngưỡng an toàn trước khi đánh giá hiệu suất.' }, { order: 2, title: 'Quy trình giải', explanation: 'Giữ các biến kiểm soát, chỉ thay biến độc lập; đọc pH/trạng thái theo thời gian và loại mọi mẻ có dấu hiệu nhiễm trước khi so năng suất.' }, { order: 3, title: 'Kết luận', explanation: 'Phương án phù hợp là “P vì an toàn quan sát được và hiệu suất cao hơn R”. Vì vậy chọn B.' }], finalAnswer: 'B', commonMistakes: ['Không nếm thử sản phẩm nghi nhiễm và không quy kết nguyên nhân khi hai mẻ khác nhau ở nhiều biến cùng lúc.'], reviewSuggestions: ['Tự đọc lại bảng/đồ thị, nêu biến và bằng chứng quyết định trước khi xem đáp án.'] }
